insert into news (id, category, title, excerpt, content, image, author, sort_order, created_at) values
(1, 'company', '14 Years and Counting: A 2012 ACONCN Cover Still Flush on a Shenzhen Main Road', 'Dated December 2012 and still perfectly level with the asphalt — one Shenzhen drainage cover is a 14-year field test our competitors would rather not talk about.', '<p>Most marketing claims about product lifespan are extrapolated in a laboratory. Ours are driving over them every day.</p><p>In December 2012, ACONCN (Happy Orient Industrial) phenolic composite drainage covers were installed on a Shenzhen municipal carriageway. The cover in the photograph still carries mixed urban traffic — buses, trucks and passenger cars — fourteen years later. Three things are worth noting for engineers who specify access covers:</p><ul><li><strong>It is still flush.</strong> There is no settlement ring, no exposed frame lip and no asphalt fracture around the frame — the classic "dark ring" that signals a failing cover installation.</li><li><strong>There is no corrosion.</strong> A cast-iron cover at the same age would show active rust bleeding through the surrounding pavement. The phenolic composite surface is chemically inert.</li><li><strong>The anti-skid tread is still legible</strong>, including the original standard marking GB/T 23858 and the installation date cast into the cover.</li></ul><p>This is the field evidence behind our 10-year replacement guarantee: a cover that holds its frame geometry does not transmit impact loads into the surrounding asphalt, and that single fact removes the single most common failure mode of municipal access covers.</p><p>Specifiers comparing cover systems for main-road duty are welcome to request the location, the SMQ load-test reports, and sample units for their own evaluation.</p>', 'assets/images/comparison/aconcn-flush.jpg', 'ACONCN Engineering', 1, '2026-08-20T09:00:00'),
(2, 'product', 'Anti-Settlement Flush Installation: How ACONCN Covers Eliminate the "Dark Ring"', 'The ugly black patch around a manhole is not a paving problem — it is a cover-frame problem. Here is the mechanics, and how a flush frame design stops it.', '<p>Drive any urban road and you will see them: dark circular scars cut into the asphalt around manhole covers. Maintenance crews patch them; they always come back. The reason is structural, and it starts below the surface.</p><h5>Why the dark ring forms</h5><p>A conventional cover sits in a narrow rigid frame. When a wheel crosses, the cover deflects and rocks inside its seating; every rocking cycle pumps the frame against the asphalt. Water enters the fracture plane, traffic compresses it, and within months a ring of fatigued asphalt — the "dark ring" — breaks down around the frame.</p><h5>The flush-mount fix</h5><p>ACONCN covers use a deep, wide-flange anti-settlement frame that transfers wheel loads into the structural course rather than the surface course:</p><ul><li>Deep frame skirts (100 mm on the AR-700H, 120 mm on the AR-900H) lock into the road build-up</li><li>A broad load-spreading flange removes the stress concentration at the frame edge</li><li>A machined cover-to-frame seat eliminates rocking, so there is no pumping action</li><li>The finished cover sits flush within 1–2 mm of the road surface</li></ul><p>The photograph shows the result on a live carriageway: no ring, no lip, no patch — years after installation.</p><h5>What to ask your supplier</h5><p>Request frame depth, flange width and a cover-seat tolerance. If a supplier cannot quantify them, the dark ring is already scheduled into your maintenance budget.</p>', 'assets/images/story/story-flush-cover.jpg', 'ACONCN Engineering', 2, '2026-08-12T09:00:00'),
(3, 'industry', 'EN 124 Load Classes A15 to F900: A No-Nonsense Selection Guide', 'Picking a cover by price instead of load class is how main roads end up with footway-grade covers. Here is exactly what A15 through F900 mean — and where each belongs.', '<p>EN 124 groups gully tops and manhole tops into six load classes according to their place of installation. Choosing one class above what you need wastes money; one class below generates replacement cycles and liability.</p><h5>The six classes</h5><ul><li><strong>A15 (15 kN)</strong> — areas exclusively for pedestrians and cyclists: garden paths, verges, indoor plant rooms.</li><li><strong>B125 (125 kN)</strong> — footways, pedestrian zones and car parks accessible only to light vehicles.</li><li><strong>C250 (250 kN)</strong> — gutter-side areas and curb zones, residential distributor roads, parking decks.</li><li><strong>D400 (400 kN)</strong> — carriageways, hard shoulders and most urban roads open to all traffic.</li><li><strong>E600 (600 kN)</strong> — areas imposing large wheel loads: ports, docks, heavy haul roads.</li><li><strong>F900 (900 kN)</strong> — exceptionally heavy-duty areas: aircraft pavements, container terminals, heavy industrial floors.</li></ul><h5>Common specification mistakes</h5><p>The most frequent error is fitting B125 or C250 covers on a D400 carriageway to save unit cost — a decision that typically reverses itself within two to three years through cover fracture and frame settlement. The second is ignoring the frame: a D400 cover in a thin frame still fails at the frame-to-road interface.</p><h5>How ACONCN maps to EN 124</h5><p>Our phenolic range spans A15 through F900 equivalents, with independent SMQ proof-load testing at 40 and 60 tonnes. Tell us the installation zone and traffic mix and we will specify the smallest class that does the job safely — not the largest class we can sell you.</p>', 'assets/images/products/refined/ar-900h.jpg', 'ACONCN Engineering', 3, '2026-07-28T09:00:00'),
(4, 'product', 'Three-Way Showdown: ACONCN Phenolic vs Standard Composite vs Cast Iron', 'Not all composite covers are the same material, and "cheaper than iron" is not a specification. A field-level comparison across the metrics that actually fail.', '<p>"Composite" covers now compete at every price point, but the word spans everything from glass-filled phenolic engineered for carriageways to low-grade resin-and-sand mixes that belong on a footway. Buyers comparing quotes line-by-line are often comparing three different products.</p><h5>Material hierarchy</h5><p><strong>Cast iron</strong> is strong but heavy, corrosive and theft-prone. <strong>Standard composite</strong> (cheap BMC/resin mixes) removes rust and scrap value but varies wildly in fiber content and load endurance. <strong>Glass-fiber reinforced phenolic</strong> — the ACONCN material — adds high-temperature compression molding and long glass-fiber reinforcement, producing a cover that is light, non-brittle and dimensionally stable for decades.</p><h5>Where the differences show up first</h5><ul><li><strong>At the frame:</strong> thin-framed cheap composites and rocking iron frames both generate settlement rings; the deep phenolic flush frame does not.</li><li><strong>Under repeated loading:</strong> low-grade composites creep and crack; iron fractures on impact after corrosion; phenolic holds its rated class.</li><li><strong>At year 10:</strong> iron is rusting, cheap composite is UV-chalked, and the phenolic cover looks essentially unchanged.</li></ul><h5>The honest comparison table</h5><p>Our full eight-row comparison — weight, load, settlement, corrosion, theft, grip, lifespan and lifecycle cost — is on the Comparison page, alongside unretouched field photographs of each material in service. Specifiers are invited to challenge any row.</p>', 'assets/images/comparison/cast-iron-dark-ring.jpg', 'ACONCN Engineering', 4, '2026-07-15T09:00:00'),
(5, 'company', 'SMQ Verifies 40-Tonne and 60-Tonne Proof Loads for AR-700H / AR-900H', 'Independent type-test reports from the Shenzhen Academy of Metrology & Quality Inspection document the load performance behind our main-road and port-duty covers.', '<p>Load-class labels are only as credible as the test behind them. ACONCN''s two flagship round covers — the AR-700H and AR-900H — have been independently type-tested by the Shenzhen Academy of Metrology & Quality Inspection (SMQ), a CMA/CNAS-accredited laboratory.</p><h5>What was tested</h5><ul><li><strong>AR-700H assembly</strong> — 700 mm clear opening in a 100 mm deep frame — verified to a 40-tonne proof load, covering D400–E600 main-road duty.</li><li><strong>AR-900H assembly</strong> — 900 mm clear opening in a 120 mm deep frame — verified to a 60-tonne proof load, the performance demanded by F900 port and airfield zones.</li></ul><h5>Why proof load matters more than a brochure number</h5><p>A type test applies the load through the standard contact block, holds it, and records residual deflection and visible cracking. A cover that merely survives a single press without measuring permanent set tells the specifier nothing. The SMQ reports record both load and deformation behavior — the data a civil engineer can actually design against.</p><h5>Request the documents</h5><p>Full reports, together with the ISO 9001, ISO 14001 and Hong Kong Green Label documents, are available on request through our Certifications page or by email. We encourage tenders and municipal procurement teams to make these reports a mandatory line item.</p>', 'assets/images/certs/smq-60t.jpg', 'ACONCN Quality', 5, '2026-06-30T09:00:00'),
(6, 'industry', 'Why Manhole Covers Sink: Root Causes and the Flush-Mount Fix', 'Cover settlement is usually diagnosed as bad compaction. The real cause is often the cover-frame assembly itself — and the fix belongs at the design stage.', '<p>A sunken manhole is one of the most expensive small defects in a road network: every patch requires traffic management, cutting, reinstatement and compaction, and most patches fail again within two years. Understanding the actual failure mechanism is the first step to stopping the cycle.</p><h5>Four root causes</h5><ol><li><strong>Load transfer through the surface course.</strong> A narrow frame concentrates wheel loads onto the asphalt right at the frame edge, where the pavement is weakest.</li><li><strong>Cover rocking.</strong> Loose manufacturing tolerances let the cover move on its seat; each wheel strike hammers the frame downward.</li><li><strong>Insufficient frame embedment.</strong> Shallow frames sit in the wearing course instead of interlocking with the base course.</li><li><strong>Compaction shadow.</strong> Compaction equipment cannot reach the wedge of material immediately around a frame, leaving a soft ring that settles first.</li></ol><h5>Designing settlement out</h5><p>The ACONCN approach attacks all four: deep skirted frames reach the structural layer; wide flanges spread loads away from the edge; machined seats stop rocking; and the flange geometry gives compaction equipment a flat target. The result is an installation that remains flush — the absence of the familiar dark ring is the visible proof.</p><h5>For asset owners</h5><p>If your reinstatement cycle around covers is shorter than five years, the frame specification — not your paving crew — is the first place to look. We are happy to review your standard detail drawing at no cost.</p>', 'assets/images/comparison/standard-composite.jpg', 'ACONCN Engineering', 6, '2026-06-10T09:00:00'),
(7, 'product', 'Pipe Repair Clamps DN25–DN400: A Selection Guide for Burst Mains', 'When a main bursts, the clock starts. This guide explains how a full-seal bolted clamp restores pressure-rated service — and how to size one in under five minutes.', '<p>A full-seal pipe repair clamp (also called a split coupling or "Haff" coupling) wraps 360° around a damaged pipe and compresses an elastomeric gasket over the defect — no cutting, no welding, no system drain-down in most cases.</p><h5>Sizing in three steps</h5><ol><li><strong>Measure the actual outside diameter</strong> of the pipe, not just its DN designation: older steel and PVC pipes of the same DN can differ in OD.</li><li><strong>Define the defect length:</strong> the clamp must overhang the crack or hole by at least 50–75 mm on each side.</li><li><strong>Match the pressure class:</strong> DN25–DN100 clamps are rated PN16; DN150 and above PN10–PN16 depending on wall build.</li></ol><h5>The ACONCN range</h5><p>Twelve standard bores from DN25 (1″) to DN400 (16″), with ductile-iron epoxy-coated shells, EPDM gaskets (NBR for hydrocarbons on request) and 304 stainless bolts. Tee (tapped) versions can be ordered on DN100 and above for live branch connections. The clamp works across steel, ductile iron, PVC and PE substrates.</p><h5>Field tips</h5><p>Clean the pipe to bright metal or smooth plastic under the gasket; torque bolts in a diagonal sequence to the values printed on the plate; and always carry one size above and below your most common main — the clamp you have at 2 a.m. is the only one that matters.</p>', 'assets/images/products/repair-clamps/dn200.gif', 'ACONCN Pipeline', 7, '2026-05-22T09:00:00'),
(8, 'industry', 'SMC, BMC or Phenolic? Choosing the Right Composite for Heavy-Traffic Covers', 'Three composite families, three very different service envelopes. A materials primer for engineers who need the cover to outlive the road.', '<p>"Fiberglass composite" covers at least three distinct material systems. Confusing them is the fastest way to buy a carriageway-rated label on a footway-grade product.</p><h5>BMC — bulk molding compound</h5><p>Short fibers (often under 6 mm) in a polyester resin paste. Cheap to mold, good surface finish, but the short fiber length limits structural toughness. BMC covers are appropriate for A15–B125 duty; specified higher, they creep and crack under repeated wheel load.</p><h5>SMC — sheet molding compound</h5><p>Longer chopped fibers (25–50 mm) impregnated as a sheet before hot-press molding. SMC delivers a genuine step up in strength and is the workhorse for C250–D400 composite covers when fiber content and press cycle are controlled.</p><h5>Phenolic — glass-fiber reinforced phenolic resin</h5><p>Phenolic resins cure into a rigid, heat-resistant, chemically stable network; combined with long glass-fiber reinforcement under high-temperature compression molding, the result is the highest-performance composite cover family — low creep, excellent fatigue behavior and the material basis of ACONCN''s D400–F900 range.</p><h5>How to tell what you are actually being quoted</h5><p>Ask four questions: resin family, fiber length and content, molding process, and the independent load-test standard. A supplier who can answer all four with documents is selling engineered product; a supplier who answers only "fiberglass" is usually selling BMC at an SMC price.</p><p>The ACONCN line uses glass-fiber reinforced phenolic precisely because our target market — main roads, ports and heavy industry — punishes the gap between a label and a material.</p>', 'assets/images/products/refined/ar-700h.jpg', 'ACONCN Materials', 8, '2026-05-08T09:00:00');
insert into site_content (id, hero_video_url, about_title, about_text, about_image, contact_title, contact_text, contact_email, contact_phone) values
(1, '', 'Flush with the road — 14 years, zero settlement', 'In December 2012, ACONCN phenolic composite drainage covers were installed on a Shenzhen municipal carriageway. They remain flush with the asphalt today — no settlement "dark ring", no rust, no replacement. That real-world record is why we build deep-flange anti-settlement frames and verify every heavy-duty class with independent SMQ proof-load tests to 40 and 60 tonnes.', 'assets/images/story/story-flush-cover.jpg', 'Contact ACONCN', 'Send us your load class, clear opening and installation zone — engineering replies within 24 hours with a specification and FOB quotation.', 'victor@aconcn.com', '+86 136 0303 8913')
insert into site_settings (key, value) values ('image_base_url', '') on conflict (key) do update set value=excluded.value;
